package local.station.controller;

import android.app.*;import android.content.*;import android.net.Uri;import android.os.Bundle;import android.webkit.*;import android.widget.*;import android.view.*;

/** Separate remote origin for publisher identity. No station key or JS interface. */
public final class CommunityActivity extends Activity {
 private WebView web;private LinearLayout layout;private ValueCallback<Uri[]> files;
 private static final String ORIGIN="https://station-studio-community.shaaaape.chatgpt.site";
 @Override public void onCreate(Bundle saved){super.onCreate(saved);getWindow().setStatusBarColor(0xfffaf9fd);getWindow().setNavigationBarColor(0xfffaf9fd);getWindow().getDecorView().setSystemUiVisibility(View.SYSTEM_UI_FLAG_LIGHT_STATUS_BAR);LinearLayout root=new LinearLayout(this);layout=root;root.setOrientation(1);root.setBackgroundColor(0xfffaf9fd);root.setFitsSystemWindows(true);LinearLayout bar=new LinearLayout(this);bar.setPadding(16,8,16,8);bar.setGravity(Gravity.CENTER_VERTICAL);Button back=new Button(this);back.setText("Готово");back.setOnClickListener(v->finish());TextView title=new TextView(this);title.setText("AliceKit · Мои публикации");title.setTextSize(17);title.setTextColor(0xff28232f);bar.addView(title,new LinearLayout.LayoutParams(0,56,1));bar.addView(back);root.addView(bar);web=new WebView(this);web.setBackgroundColor(0xfffaf9fd);web.getSettings().setJavaScriptEnabled(true);web.getSettings().setDomStorageEnabled(true);web.getSettings().setAllowFileAccess(false);web.getSettings().setAllowContentAccess(false);web.getSettings().setMixedContentMode(WebSettings.MIXED_CONTENT_NEVER_ALLOW);web.getSettings().setSupportMultipleWindows(false);web.getSettings().setUserAgentString(web.getSettings().getUserAgentString()+" Kontur/2.5");
 web.setWebViewClient(new WebViewClient(){@Override public void onReceivedHttpError(WebView v,WebResourceRequest request,WebResourceResponse response){if(request.isForMainFrame()&&response.getStatusCode()>=400)unavailable();}@Override public void onReceivedError(WebView v,WebResourceRequest request,WebResourceError error){if(request.isForMainFrame())unavailable();}@Override public boolean shouldOverrideUrlLoading(WebView v,String address){try{Uri u=Uri.parse(address);String h=u.getHost();return !"https".equals(u.getScheme())||h==null||!(h.equals("station-studio-community.shaaaape.chatgpt.site")||h.equals("chatgpt.com")||h.equals("auth.openai.com")||h.equals("auth0.openai.com")||h.equals("auth0.com")||h.endsWith(".auth0.com"));}catch(Exception e){return true;}}});
 web.setWebChromeClient(new WebChromeClient(){@Override public boolean onShowFileChooser(WebView v,ValueCallback<Uri[]> cb,FileChooserParams p){if(files!=null)files.onReceiveValue(null);files=cb;Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT);i.addCategory(Intent.CATEGORY_OPENABLE);i.setType("*/*");try{startActivityForResult(i,81);}catch(Exception e){files.onReceiveValue(null);files=null;}return true;}@Override public boolean onJsConfirm(WebView v,String u,String text,JsResult r){new AlertDialog.Builder(CommunityActivity.this).setMessage(text).setPositiveButton("Продолжить",(d,w)->r.confirm()).setNegativeButton("Отмена",(d,w)->r.cancel()).setOnCancelListener(d->r.cancel()).show();return true;}});
 root.addView(web,new LinearLayout.LayoutParams(-1,0,1));setContentView(root);web.loadUrl(ORIGIN+"/app");}
 private void unavailable(){runOnUiThread(()->{web.setVisibility(View.GONE);if(layout.getChildCount()>2)return;LinearLayout info=new LinearLayout(this);info.setOrientation(1);info.setPadding(32,36,32,32);TextView note=new TextView(this);note.setText("Публикации сейчас недоступны на этом устройстве. Сервер не разрешил подключение или связь прервалась. Каталог и установка плагинов доступны в основной панели.");note.setTextSize(16);note.setTextColor(0xff6f637b);info.addView(note);Button retry=new Button(this);retry.setText("Повторить подключение");retry.setAllCaps(false);retry.setOnClickListener(v->{layout.removeView(info);web.setVisibility(View.VISIBLE);web.loadUrl(ORIGIN+"/app");});info.addView(retry);layout.addView(info);});}
 @Override protected void onActivityResult(int code,int result,Intent data){super.onActivityResult(code,result,data);if(code==81&&files!=null){files.onReceiveValue(result==RESULT_OK&&data!=null&&data.getData()!=null?new Uri[]{data.getData()}:null);files=null;}}
 @Override public void onBackPressed(){if(web.canGoBack())web.goBack();else finish();}
 @Override public void onDestroy(){if(files!=null)files.onReceiveValue(null);web.destroy();super.onDestroy();}
}
